<?php
require __DIR__.'/../includes/config.php';require __DIR__.'/../includes/functions.php';$u=require_role(['owner']);
$st=$pdo->prepare('SELECT r.*,c.name category_name FROM requests r JOIN categories c ON c.id=r.category_id WHERE r.owner_id=? ORDER BY r.created_at DESC');$st->execute([$u['id']]);$rows=$st->fetchAll();$pageTitle='My Requests';require __DIR__.'/../includes/header.php';?>
<div class="eyebrow">REQUEST HISTORY</div><h2>My <span class="red">Requests</span></h2><p class="subtext">Follow every request from receipt to resolution.</p><div class="card"><?php if(!$rows):?><div class="empty">You haven't submitted a request yet.<br><a class="btn btn-primary" style="margin-top:12px" href="<?=BASE_URL?>/owner/report.php">＋ Report an Issue</a></div><?php else:?><div class="table-wrap"><table class="table"><thead><tr><th>Request</th><th>Issue type</th><th>Date</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['request_no'])?></strong><br><small class="muted"><?=e($r['title'])?></small></td><td><?=e($r['category_name'])?></td><td><?=e(date('d M Y',strtotime($r['created_at'])))?></td><td><span class="badge <?=status_class((int)$r['status'])?>"><?=e(status_names()[$r['status']])?></span></td><td><a class="btn btn-secondary btn-sm" href="<?=BASE_URL?>/owner/status.php?id=<?=$r['id']?>">View status</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div><?php require __DIR__.'/../includes/footer.php';?>
